with matched_keys as (select account_type from accounts intersect all select account_type from accounts where status = 'FROZEN'), verified as (select s.* from accounts s join matched_keys k on s.account_type = k.account_type) select case when balance >= 69000 then 'HIGH' else 'LOW' end as balance_tier, status, count(case when account_type = 'CHECKING' then 1 end) as checking_count, count(case when account_type = 'CREDIT' then 1 end) as credit_count, count_if(status = 'OPEN') as open_events from verified group by case when balance >= 69000 then 'HIGH' else 'LOW' end, status;
